    dollars = abs_cents // 100
    remaining_cents = abs_cents % 100

    # Format the number part with thousands separator
    formatted_number = f"{dollars:,}.{remaining_cents:02d}"

    if cents < 0:
        if symbol:
            return f"-{symbol}{formatted_number}"
        else:
            return f"-{formatted_number}"
    else:
